WITH payload AS (SELECT $archive_payload$[{"id":"0ff7df29-5700-57ad-8bb1-534f44a64a89","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع مواد سباكة -موافقة الكفيل على سداد الثمن - االمتناع عن السداد للعيب -املطالبة بالسداد -شهادة الشهود العدول -طلب الرجوع يف البيع للعيب يكون فور العلم بالعيب -إلزام املدعى عليه بتسليم املبلغ املدعى به .","document_number":"3430669","case_number":"3387968","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف والقائم بعمل املكتب القضائي الرابع بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/5","year":"1434","subject":"بيع -بيع مواد سباكة -موافقة الكفيل على سداد الثمن - االمتناع عن السداد للعيب -املطالبة بالسداد -شهادة الشهود العدول -طلب الرجوع يف البيع للعيب يكون فور العلم بالعيب -إلزام املدعى عليه بتسليم املبلغ املدعى به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/5 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3430669 :‬‬\n                    ‫َر ْق ُم الدعوى‪3387968 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34264857‬تاريخه‪1434/7/10 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع مــواد ســباكة ‪ -‬موافقــة الكفيــل علــى ســداد الثمــن ‪-‬‬\n‫االمتنــاع عــن الســداد للعيــب ‪ -‬املطالبــة بالســداد ‪ -‬شــهادة الشــهود‬\n‫العــدول ‪ -‬طلــب الرجــوع يف البيــع للعيــب يكــون فــور العلــم بالعيــب‬\n                     ‫‪ -‬إلــزام املدعــى عليــه بتســليم املبلــغ املدعــى بــه ‪.‬‬\n\n\n\n\n‫‪ -‬مــا جــاء يف كشــاف القنــاع (فمــن علــم العيــب وأخــر الــرد بــه لــم‬\n‫يبطــل خيــره بالتأخيــر إال أن يوجــد منــه مــا يــدل علــى الرضــا مــن‬\n                                      ‫تصــرف يف املبيــع أو نحــوه) ‪. 460/7‬‬\n\n\n\n\n‫ادعــى املدعــي أنــه بــاع لعامــل يعمــل يف مؤسســة مــوكل املدعــى عليــه‬\n‫وحتــت كفالتــه بضاعــة عبــارة عــن مــواد ســباكة‪ ،‬مت االتفــاق مــع‬\n‫الكفيــل علــى ســداد ثمــن البضاعــة علــى أقســاط قــام بســداد بعضهــا‬\n‫وامتنــع عــن ســداد باقــي األقســاط بحجــة أن البضاعــة بهــا عيــوب‪ ،‬متــت‬\n‫مطالبــة املدعــى عليــه بالســداد إال أنــه رفــض‪ ،‬قــدم املدعــي شــهود ًا‬\n‫عــدو ًال علــى صحــة دعــواه‪ ،‬وترتيب ـ ًا علــى ذلــك وملــا كان املدعــى عليــه‬\n‫قــد صــادق علــى صحــة املســتند املقــدم إلــى احملكمــة املذيــل بتوقيعــه‬\n‫مؤكــد ًا علــى صحــة االتفــاق الســابق وقيامــه بســداد جــزء مــن املبلــغ‬\n\n                                                                                    ‫‪172‬‬\n\f      ‫علــى دفعــات وإقــراره بذلــك وعــدم طعنــه يف العيــب إال بعــد مــدة طويلــة‬\n      ‫مــن الشــراء‪ ،‬لــذا حكمــت احملكمــة عليــه بتســليم باقي املبلــغ للمدعي‬\n                                    ‫‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬لــدي‬\n      ‫أنــا (‪ )....‬القاضــي يف احملكمــة العامــة بالطائــف والقائــم بعمــل املكتب‬\n      ‫القضائــي الرابــع بنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس برقــم‬\n      ‫‪ 3387968‬وتاريــخ ‪1433/2/3‬ه ـ واملقيــدة يف هــذه احملكمــة برقــم‬\n      ‫‪ 33231147‬وتاريــخ ‪1433/2/3‬ه ـ ففــي هــذا اليــوم الثالثــاء املوافــق‬\n      ‫‪1433/5/4‬ه ـ ويف متــام الســاعة احلاديــة عشــر صباح ـ ًا حضــر ‪............‬‬\n      ‫ســوري اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ .............‬وأدعــى علــى‬\n      ‫احلاضــر معــه يف مجلــس احلكــم ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫ا عــن ‪ ..........‬بالوكالــة الصــادرة‬    ‫املدنــي رقــم ‪...............‬بصفــة وكي ـ ً‬\n      ‫مــن كتابــة عــدل الطائــف الثانيــة برقــم‪ 10475‬وتاريخ‪1433/2/20‬ه ـ‬\n      ‫و املخــول لــه فيهــا حــق املدافعــة واملرافعــة و اإلقــرار و اإلنــكار‬\n      ‫ا يف دعــواه‪ :‬أننــي بعــت علــى العامــل ‪.........‬‬  ‫وقبــول احلكــم ونفيــه قائ ـ ً‬\n      ‫الباكســتاني والــذي يعمــل يف مؤسســة مــوكل املدعــى عليــه وحتــت‬\n      ‫كفالتــه بضاعــة عبــارة عــن مــواد ســباكة مببلــغ قرابــة مائــة وســتة‬\n      ‫وتســعون ألــف ريــال ولــم نثبتهــا وبعــد ذلــك اجتهنــا إلــى احملــل مــع بعــض‬\n      ‫املصلحــن لكــي نثبــت حقنــا وبعــد اجللــوس مــع العامــل ثبــت املبلــغ مائــة‬\n      ‫وخمســة وعشــرون الف ريال واســتلمنا مبلغ خمســة وعشــرون الف ريال‬\n      ‫ثــم طلــب منــا أن نحضــر ملقابلــة كفيــل املدعــى عليــه و عنــد جلوســنا‬\n\n‫‪173‬‬\n\f‫معــه اتفقنــا علــى أن يســلم لنــا مبلــغ قــدرة مائــة الــف ريــال علــى أقســاط‬\n‫تدفــع نهايــة كل شــهر خمســة أالف ريــال وقــال لنــا مــوكل املدعــى عليه‬\n‫اكتبوهــا بســند قــرض حســن وقامــوا بتقســيط املبلــغ ثالثــة أقســاط ثــم‬\n‫امتنعــوا بعــد ذلــك عــن دفــع املبلــغ أطلــب إلــزام مــوكل املدعــى عليــه‬\n‫بتســديد مبلــغ قــدره خمســة وثمانــون الــف ريــال وهــو حــال يف ذمتــه‬\n‫هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه وكالــة وســؤاله أجــاب‬\n‫قائـاً‪ :‬بــأن مــا ذكــره املدعــي غيــر صحيــح و الصحيــح أن املدعــي قــام‬\n‫باالتفــاق مــع العامــل املوجــود حتــت كفالــة موكلــي وقــام بشــراء منــه‬\n‫أدوات الســباكة وقامــوا بكتابــة ســند قــرض حســن صوريـ ًا والبضاعــة‬\n‫موجــوده لــدى موكلــي يف املســتودع وفيهــا عيــوب وأمــا بالنســبة حلضــور‬\n‫موكلــي ملجلــس االتفــاق مــع املدعــي فــا أعلــم عــن ذلــك وســوف أرجــع‬\n‫ملوكلــي للســؤال عــن ذلــك و إلحضــار املدعــى عليــه أصالــة رفــع اجللســة‬\n‫وحــدد للطرفــن موعــد ًا يف يــوم األثنــن املوافــق ‪1433/7/14‬ه ـ يف متــام‬\n‫الســاعة العاشــرة صباح ـ ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                              ‫محمــد حــرر يف ‪1433/5/4‬هــ‪.‬‬\n‫احلمــد اهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n‫فلــدي أنــا ‪ ........‬القاضــي املنتــدب باحملكمــة العامــة بالطائــف بنــاء‬\n‫علــى قــرار معالــي رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 33/9116‬يف‬\n‫‪1433/4/21‬ه ـ وبنــاء علــى خطــاب فضيلــة رئيــس احملكمــة العامــة‬\n‫بالطائــف رقــم ‪ 33786591‬يف ‪1433/4/26‬ه ـ املتضمــن تكليفــي‬\n‫بالعمــل يف القســم القضائــي الرابــع يف احملكمــة وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلتــه برقم ‪ 3387968‬وتاريــخ ‪1433/2/3‬هـ واملقيدة‬\n‫يف هــذه احملكمــة برقــم ‪ 33231147‬وتاريــخ ‪1433/2/3‬ه ـ ففــي هــذا‬\n\n\n                                                                                       ‫‪174‬‬\n\f      ‫اليــوم االثنــن املوافــق ‪1433/7/14‬ه ـ ويف متــام الســاعة التاســعة صباحا‬\n      ‫فتحــت اجللســة وفيهــا حضــر ‪ ...............‬ســوري اجلنســية مبوجــب رخصــة‬\n      ‫اإلقامة رقم ‪ ............‬وحضر حلضوره ‪ .............‬ســعودي اجلنســية مبوجب‬\n      ‫ا عــن ‪ ..........‬ســعودي اجلنســية‬\n                                        ‫الســجل املدنــي رقــم ‪ ........‬بصفــة وكي ـ ً‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .........‬بالوكالــة الصــادرة مــن كتابــة‬\n      ‫عــدل الطائــف الثانيــة برقــم‪ 10475‬وتاريخ‪1433/2/20‬ه ـ والتــي تخولــه‬\n      ‫حــق إقامــة وســماع عمــوم الدعــاوى واملطالبــات املقامــة منــي أو ضــدي‬\n      ‫مــع أي شــخص كان يف أي جهــة كانــت وأمــام أي محكمــة واملدافعــة‬\n      ‫وحضــور اجللســات وتقــدمي البينــات واإلقــرار واإلنــكار وتقــدمي لوائــح‬\n      ‫االدعــاء واالعتــراض وإحضــار الشــهود واســتئناف األحــكام والقناعــة‬\n      ‫بهــا ومتييــز األحــكام وبقــراءة مــا ســبق ضبطــه علــى الطرفــن صادقــا‬\n      ‫عليــه وبســؤال املدعــى عليــه وكالــة عمــا أســتمهل ألجلــه أجــاب قائــا‬\n      ‫مــا يخــص حضــور موكلــي مجلــس االتفــاق فأجــاب قائــا نعــم لقــد‬\n      ‫حضــر موكلــي مجلــس التعاقــد ووقــع علــى االتفــاق ولكــن موكلــي لــم‬\n      ‫يوقــع علــى أنهــا قــرض حســن وإمنــا وقــع علــى أنهــا قيمــة بضاعــة هكــذا‬\n      ‫أجــاب فجــرى عــرض ورقــة التعاقــد علــى املدعــى عليــه وكالــة وأنــه جــاء‬\n      ‫فيهــا مــا نصــه (وذلــك املبلــغ هــو عبــارة عــن قــرض حســن) فأجــاب قائــا‬\n      ‫بــأن هــذا توقيــع موكلــي وختــم مؤسســة ولكــن موكلــي ضعيــف يف‬\n      ‫القــراءة وثقيــل الســمع وال يعلــم أن املكتــوب قــرض حســن هكــذا‬\n      ‫أجــاب وبعــرض ذلــك علــى املدعــى أصالــة أجــاب قائــا الصحيــح مــا‬\n      ‫ذكرتــه واطلــب إلــزام املدعــى عليــه أصالــة بدفــع حقــي كامــا هكــذا‬\n      ‫أجــاب وقــال املدعــى عليــه وكالــة أمــا مــا يخــص عــدم حضــور موكلــي‬\n      ‫يف هــذه اجللســة فألنــه يجــري غســيل للكلــى يف مستشــفى الهــدا هــذا‬\n\n\n‫‪175‬‬\n\f‫اليــوم وســأحضر إفــادة بذلــك يف اجللســة القادمــة هكــذا أجــاب وبطلبــه‬\n‫املدعــي البينــة علــى مــا ذكــر اســتعد بذلــك ورفعــت اجللســة كذلــك‬\n‫وتأجلــت إلــى يــوم األحــد املوافــق ‪1433/11/7‬هـ الســاعة التاســعة وباهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/7/14‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 3387968‬وتاريــخ ‪1433/02/03‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33231147‬وتاريــخ ‪1433/02/03‬ه ـ ففــي يوم األحد‬\n‫املوافــق ‪1434/01/04‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباحــا‬\n‫وفيهــا حضــر املدعــي أصالــة ‪ ...........‬ســوري اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم ‪ .............‬وحضــر حلضــوره ‪ ........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ..........‬وبتــاوة مــا دون ســبقا عليهمــا صادقــا عليــه‬\n‫جملــة وتفصيــا بنــاء علــى املــادة السادســة والســتون بعــد املائــة مــن‬\n‫نظــام املرافعــات الشــرعية ثــم جــرى عــرض دعــوى املدعــي علــى املدعــى‬\n‫عليــه احلاضــر فأجــاب بقولــه إننــي صاحــب مؤسســة ‪ ................‬بنــاء‬\n‫وســباكه وكان لــي موظــف باكســتاني يديــر احملــل يف فتــرة مرضــي‬\n‫وقــد اشــترى بضاعــة مــن الســوري احلاضــر وكانــت بضاعــة ســيئة‬\n‫جــدا وال أعلــم كــم قيمتهــا وقــد حضــرت لالتفــاق الــذي جــرى بينهمــا‬\n‫علــى تقســيط املبلــغ ولــم أكــن أقــرأ او أســمع جيــدا ووقعــت علــى ورقــة‬\n‫الصلــح املرفقــة وأنــا غيــر مســتعد بالســداد ألن البضاعــة ال علــم لــي بهــا‬\n‫وقــد خســرتني كثيــرا هكــذا أجــاب وبــرد ذلــك علــى املدعــي أجــاب‬\n‫بقولــه الصحيــح مــا ذكــرت وقــد وقــع بعلمــه وحضــوره وقــد تنازلــت‬\n‫عــن جــزء مــن مبلــغ البضاعــة قبــل حضــوره هكــذا قــرر وبطلــب البينــة‬\n\n\n                                                                                     ‫‪176‬‬\n\f      ‫مــن املدعــي علــى مــا يدعيــه أبــرز ورقــة مطبوعــة مطبوعــات مؤسســة‬\n      ‫‪ ...............‬بتاريــخ ‪1431/4/21‬ه ـ ونــص احلاجــة منهــا (مت االتفــاق بــن‬\n      ‫كل مــن ‪...............‬و‪ ............‬وقــد اتفــق الطرفــن علــى أن يدفــع ‪............‬‬\n      ‫مبلــغ خمســة آالف ريــال يف كل شــهر هجــري ابتــداء مــن نهايــة شــهر‬\n      ‫جمــادى األول عــام ‪1431‬ه ـ ملــدة عشــرين شــهر بحيــث يكــون إجمالــي‬\n      ‫املبلــغ مائــة ألــف ريــال وذلــك املبلــغ عبــاره عــن قــرض حســن وعلــى ذلــك‬\n      ‫وقــع الطرفــن ‪ ...‬وموقــع مــن قبــل الطرفــن باإلضافــة إلــى الشــاهد‬\n      ‫‪.....................‬والشــاهد ‪ ..............‬وختــم املؤسســة)أ‪.‬هـ‪ .‬كمــا أحضــر‬\n      ‫الشــهود يف مجلــس االتفــاق وهــم ‪ ...................‬ســعودي بالســجل املدنــي‬\n      ‫رقــم ‪....................‬و‪ .........................‬ســعودي بالســجل املدنــي رقــم‬\n      ‫‪ ...................‬وبســؤال األول عن شــهادته وهو صاحب مؤسســة ‪..............‬‬\n      ‫ويســكن يف حــي الشــهداء اجلنوبيــة ويبلــغ مــن العمــر ســبعه وخمســون‬\n      ‫عامــا وهــو جــار للمدعــي أجــاب بقولــه أشــهد بــاهلل العلــي العظيــم أننــي‬\n      ‫وقعــت علــى الورقــة التــي أبرزهــا املدعــي واملرصــودة أعــاه وكان‬\n      ‫ذلــك بحضــور املدعــى عليــه أصالــه ومت االتفــاق علــى تقســيط مائــة‬\n      ‫ألــف ريــال كل شــهر خمســة أالف ريــال قــرض حســن هكــذا شــهد‬\n      ‫وبســؤال الثانــي عثمــان عــن شــهادته وهــو يعمــل معلــم ابتدائــي ويبلــغ‬\n      ‫مــن العمــر ســبعة وثالثــون عامــا ويســكن يف حــي الشــهداء اجلنوبيــة‬\n      ‫ولــه عالقــة وديــة مــع املدعــي مــن قــدمي أجــاب بقولــه أشــهد بــاهلل العلــي‬\n      ‫العظيــم أننــي وقعــت علــى الورقــة التــي أبرزهــا املدعــي املرصــودة أعــاه‬\n      ‫وكان ذلــك بحضــور املدعــى عليــه ومت اإلتفــاق بتقســيط مائــة ألــف‬\n      ‫ريــال كل شــهر خمســة أالف ريــال قــرض حســن هكــذا شــهد ثــم جــرى‬\n      ‫ســؤال الشــاهدين ملــاذا مت توثيــق الديــن علــى أنــه قــرض حســن وليــس‬\n\n\n‫‪177‬‬\n\f‫قيمــة بضاعــة فأجابــا جميعــا بــأن ذلــك حســب رغبــة املدعــى عليــه ألنــه‬\n‫ذكــر أن املبلــغ يف ذمتــه ويرغــب توثيقــة كقــرض حســن هكــذا قــررا‬\n‫كمــا قــرر املدعــي أنــه أســتلم ثالثــة أقســاط وتبقــى خمســة وثمانــون‬\n‫ألــف ريــال وهكــذا قــررا وبعــرض شــهادة الشــاهدين علــى املدعــى‬\n‫عليــه أجــاب بقولــه أمــا الشــاهد األول فلــم يحضــر ولــم أره مــن قبــل أمــا‬\n‫الشــاهد الثانــي فهــو نســيب للمدعــي وزوج إلبنتــه كمــا قــرر أنــه ســلم‬\n‫ثالثــة أقســاط للمدعــي هكــذا قــرر ثــم قــررت رفــع اجللســة إلحضــار‬\n‫مزكــن لشــهود املدعــي وعليــه رفعــت اجللســة وحــدد للطرفــن موعــد‬\n‫يــوم الثالثــاء املوافــق ‪1434/2/5‬ه ـ ختمــت اجللســة الســاعة العاشــرة و‬\n‫النصــف صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/04‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ففــي يــوم الثالثــاء املوافق‪1434/02/05‬ه ـ افتتحــت اجللســة‬\n‫الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي أصالــة ‪ ..........‬املدونــة‬\n‫هويتــه ســابقا كمــا حضــر حلضــوره املدعــى عليــه وكالــة ‪..............‬‬\n‫املدونــة هويتــه ووكالتــه ســابقا وبســؤال املدعــي عمــا اســتمهل ألجلــه‬\n‫أجــاب بقولــه إننــي أحضــرت مزكــن للشــهود الذيــن أحضرتهــم ثــم‬\n‫حضــر ‪ ..........‬ســعودي بالســجل املدنــي رقــم ‪..........‬و‪ ..............‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪ .............‬وبســؤالهما عمــا لديهمــا أجابــا بقولهمــا‬\n‫إننــا نشــهد بعدالــة وثقــة الشــاهد ‪ ........‬وأنــه حســن الســيرة ومقبــول‬\n‫الشــهادة لنــا وعلينــا كمــا حضــر ‪ .........‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪............‬و‪ ..........‬ســعودي بالســجل املدنــي رقــم ‪ ..........‬وبســؤالهما‬\n‫عمــا لديهمــا أجابــا بقولهمــا إننــا نشــهد بعدالــة وثقــة الشــاهد ‪............‬‬\n\n\n                                                                                       ‫‪178‬‬\n\f      ‫وأنــه حســن الســيرة ومقبــول الشــهادة لنــا وعلينــا هكــذا قــرر اجلميــع‬\n      ‫ثــم جــرى ســؤال املدعــي عــن الشــاهد ‪ .........‬هــل زوج البنتــه قــال غيــر‬\n      ‫صحيــح وليــس لــي عالقــة نســب بــه البتــة هكــذا قــرر ثــم جــرى ســؤال‬\n      ‫الطرفــن هــل لديهمــا مزيــد بينــة فقــرر كل واحــد منهمــا باكتفائــه مبا‬\n      ‫ســبق تقدميــه مــن قبــل فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي أصالــة‬\n      ‫وإجابــة املدعــى عليهمــا أصالــة ووكالــة وحيــث صــادق املدعــى عليــه‬\n      ‫أصالــة علــى صحــة الورقــة املكتوبــة واملوقعــة بينهمــا وحيــث شــهدت‬\n      ‫البينــة املعدلــة شــرعا علــى حضــوره ورضــاه وتوقيعــه وقيامــه بســداد‬\n      ‫جــزء مــن الدفعــات وإقــراره بذلــك وألنــه تصــرف يف املبيــع ممــا يــدل‬\n      ‫علــى رضــاه بــه ولــم يطعــن بالعيــب إال بعــد مضــي مــدة طويلــة وبعــد رفــع‬\n      ‫الدعــوى ضــده جــاء يف كشــاف القنــاع (فمــن علــم العيــب وأخــر الــرد‬\n      ‫بــه لــم يبطــل خيــره بالتأخيــر إال أن يوجــد منــه مــا يــدل علــى الرضــا مــن‬\n      ‫تصــرف يف املبيــع أو نحــوه) ‪ 460/7‬لذلــك كلــه فقــد حكمــت علــى‬\n      ‫املدعــى عليــه أصالــة بتســليم املدعــي مبلــغ خمســة وثمانــون ألــف ريــال‬\n      ‫وبعرضــه عليهمــا قــرر املدعــي قناعتــه باحلكــم كمــا قــرر املدعــى عليــه‬\n      ‫وكالــة عــدم القناعــة فجــرى إفهامــه بــأن لــه حــق االعتــراض بطلــب‬\n      ‫االســتئناف وذلــك خــال ثالثــون يومــا مــن تاريــخ اســتالمه احلكــم وذلــك‬\n      ‫بتقــدمي الئحــة اعتراضيــة وإن مضــت املــدة دون تقــدمي الئحــة اعتراضيــة‬\n      ‫اكتســب احلكــم القطعيــة وختمــت اجللســة الســاعة العاشــرة والنصــف‬\n      ‫صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/05‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف ففــي يــوم الثالثــاء املوافــق‪ 1434/05/21‬ه ـ افتتحــت اجللســة‬\n\n\n‫‪179‬‬\n\f‫الســاعة الواحــدة والربــع وفيهــا حضــر الطرفــان املدعــي واملدعــى عليــه‬\n‫وكالــة املدونــة هوياتهمــا ســابقا وكان قــد وردنــا قــرار محكمــة‬\n‫االســتئناف الدائــرة احلقوقيــة الرابعــة مبنطقــة مكــة املكرمــة برقــم‬\n‫‪ 3459777‬يف ‪1434/3/10‬ه ـ املتضمــن مــا نصــه (وبدراســة احلكــم‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة إعــادة املعاملــة‬\n‫لفضيلــة حاكمهــا ملناقشــة مــا ورد يف الالئحــة االعتراضيــة املقدمــة‬\n‫مــن املدعــى عليــه بحضــور الطرفــن وإجــراء املقتضــى الشــرعي نحــوه‬\n‫وخاصــة الفقــرات الرابعــة والسادســة الفقــرة ب مــن الســابعة وبــاهلل‬\n‫التوفيــق قاضــي اســتئناف ‪ ............‬و ‪............‬موافــق علــى احلكــم و‪.........‬‬\n‫ختــم وتوقيــع) وعليــه أجيــب أصحــاب الفضيلــة بأنــه جــرى عــرض الفقــرة‬\n‫الرابعــة علــى املدعــي فأجــاب بقولــه أننــي بينــت أننــي بعــت علــى املدعــى‬\n‫عليــه مــواد صحيــة وهــي شــطافات وخالطــات ومحابــس ورفــوف‬\n‫واكسســوارت ومغاســل واكــواع وبزابيــز وهــي موجــودة كاملــة‬\n‫بالكميــة والنــوع وهــذه صــورة منهــا ثــم ابــرز ثالث ورقــات هكذا اجاب‬\n‫ثــم جــرى إحلاقهــا يف املعاملــة وبعــرض الفقــرة السادســة علــى الطرفــن‬\n‫املتضمنــة بــان املدعــى عليــه اطلــع علــى البضاعــة وعايــن العيــب واختــار‬\n‫فســخ الشــراء أجــاب املدعــي بــأن هــذا لــم يحصــل وهــو غيــر صحيــح بــل‬\n‫ان املدعــى عليــه قــام بســداد ثالثــة أقســاط ممــا يــدل علــى قبولــه وعــدم‬\n‫طعنــه مبــا ذكــره مــن حــدوث العيــب كمــا قــرر املدعــى عليــه وكالــة‬\n‫أن العامــل الــذي يعمــل لــدى موكلــه فعــا قــام بســداد ثالثــة أقســاط‬\n‫ثــم توقــف وأمــا مــا يخــص الفقــرة ب مــن الفقــرة الســابعة واملتضمنــة‬\n‫تصــرف املدعــى عليــه بالبضاعــة فقــد ســبق ان اقــر املدعــى عليــه اصالــة‬\n‫بــان البضاعــة قــد خســرته كثيــرا كمــا اقــر يف هــذه اجللســة املدعــى‬\n\n\n                                                                                         ‫‪180‬‬\n\f      ‫عليــه وكالــة ان موكلــه قــد تصــرف ببعــض البضاعــة الســليمة ثــم‬\n      ‫تبــن لــه وجــود بعــض العيــوب يف باقــي البضاعــة هكــذا اجــاب هــذا‬\n      ‫مــا لــزم اجلــواب عليــه والزلــت علــى مــا حكمــت بــه ســابقا وقــررت اعــادة‬\n      ‫املعاملــة حملكمــة االســتئناف لالطــاع وتدقيــق احلكــم وختمــت اجللســة‬\n      ‫الســاعة الواحــدة والنصــف ظهــرا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف ففــي يــوم األربعــاء املوافــق‪ 1434/07/26‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة العاشــرة صباحــا وكان قــد وردنــا قــرار محكمــة االســتئناف‬\n      ‫الدائــرة احلقوقيــة الرابعــة مبكــة املكرمــة رقــم ‪ 34264857‬وتاريــخ‬\n      ‫‪1434/07/10‬ه ـ واملتضمــن مــا نصــه (وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء‬\n      ‫األخيــر واهلل املوفــق ‪ ،‬قضــاة اســتئناف ‪ ، .........‬و‪ ، ............‬و‪.............‬‬\n      ‫ختــم وتوقيــع ) ومبوجــب قــرار محكمــة االســتئناف اكتســب احلكــم‬\n      ‫القطعيــة لــذا جــرى إثباتــه حتــى ال يخفــى وختمــت اجللســة العاشــرة‬\n      ‫والربــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/07/26‬ه ـ ‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":172,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0e74534a7af79a12686f2f289d1ce4716f0b68697e7557d8e39a0ab21cfdcacd","normalized_text_hash":"374a6992d1e6e486a7342ea34573fa0afa4d19961fbfd13d1e84272320ea1775","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p172-3430669"},{"id":"65ea140c-2e4e-5a61-bfac-c07c96dc09bf","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد عينة -شراء املدعى عليه مكيفات مبوجب عقد وكمبياالت بثمن آجل -كفالة غرم وأداء وتسليم -قيام املدعى عليه ببيع املكيفات للبائع بثمن حال -مصادقة املدعى عليه على ما جاء يف الدعوى -إلزام املدعى عليه بدفع رأس املال دون األرباح حلرمة بيع العينة .","document_number":"33238846","case_number":"3392948","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":"الدائرة احلقوقية اخلامسة يف محكمة الاستئناف مبنطقة مكة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/10","year":"1434","subject":"بيع -عقد عينة -شراء املدعى عليه مكيفات مبوجب عقد وكمبياالت بثمن آجل -كفالة غرم وأداء وتسليم -قيام املدعى عليه ببيع املكيفات للبائع بثمن حال -مصادقة املدعى عليه على ما جاء يف الدعوى -إلزام املدعى عليه بدفع رأس املال دون األرباح حلرمة بيع العينة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/5/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33238846 :‬‬\n                    ‫َر ْق ُم الدعوى‪3392948 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3444605‬تاريخه‪1434/2/23 :‬هـ‬\n\n\n‫بيــع ‪ -‬عقــد عينــة ‪ -‬شــراء املدعــى عليــه مكيفــات مبوجــب عقــد‬\n‫وكمبيــاالت بثمــن آجــل ‪ -‬كفالــة غــرم وأداء وتســليم ‪ -‬قيــام املدعــى‬\n‫عليــه ببيــع املكيفــات للبائــع بثمــن حــال ‪ -‬مصادقــة املدعــى عليــه علــى‬\n‫مــا جــاء يف الدعــوى ‪ -‬إلــزام املدعــى عليــه بدفــع رأس املــال دون األربــاح‬\n                                                         ‫حلرمــة بيــع العينــة ‪.‬‬\n\n\n\n\n                         ‫عقد العينة عقد محرم على رأي جمهور العلماء ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بــأن املدعــى عليــه الغائــب عــن مجلــس احلكــم‬\n‫قــد كفــل كفالــة غــرم وأداء وتســليم ملوكلــه كمــا هــو منصــوص يف‬\n‫العقــد املرفــق والكمبيالــة ‪ -‬وقــد قــام املكفــول بشــراء خمســة عشــر‬\n‫مكيفــا مببلــغ وقــدره ســبعة وعشــرون ألــف ريــال مبوجــب العقــد املبــرم‬\n‫املرفــق باملعاملــة ومبوجــب الكمبيالــة ولــم يســدد مكفولــه إال مبلغ ـ ًا‬\n‫وقــدره ألفــا ريــال فقــط وبقــي مبلــغ وقــدره خمســة وعشــرون ألــف ريــال‬\n‫وقــد حــل املبلــغ كامــا وطلــب إلــزام املدعــى عليــه بدفــع املبلــغ كامـاً‪-‬‬\n‫وأوضــح املدعــي وكالــة بعــد ذلــك بقولــه ‪ :‬لقــد اشــترى املكفــول مــن‬\n‫موكلــي خمســة عشــر مكيفــا وبعــد املعاينــة باعهــا علــى البائــع نفســه ‪-‬‬\n\n                                                                                    ‫‪182‬‬\n\f      ‫صــادق املدعــى عليــه مبــا جــاء يف الدعــوى ‪ -‬وجــرى االطــاع علــى العقــد‬\n      ‫‪ -‬إلعتــراف املدعــي وكالــة واملدعــى عليــه بــأن البيــع بيــع عينــة وهــو‬\n      ‫محــرم وال يصــح علــى قــول جماهيــر أهــل العلــم‪ ،‬فــا يترتــب عليــه أي‬\n      ‫أثــر‪ ،‬ونظــر ًا إلــى حــال املدعــي واملدعــى عليــه فهمـ ًا يظنــان أن مــا قامــا‬\n      ‫بــه ال شــيء فيــه وأنــه مــن البيــع املبــاح ‪ ،‬ولــذا فهمــا قــد رضيــا بــه ‪ ،‬لذلــك‬\n      ‫كلــه فقــد ألزمــت املدعــى عليــه ‪ ......‬بدفــع مبلــغ وقــدره ثالثة عشــر ألف‬\n      ‫ريــال فقــط وهــو مــا تبقــى مــن رأس املــال ورددت دعــوى املدعــي وكالــة‬\n      ‫فيمــا زاد عــن ذلــك للســبب املذكــور آنف ـ ًا وبذلــك حكمــت مــع بيــان‬\n      ‫حقيقــة مــا جــرى بينهمــا وأنــه محــرم ‪ -‬أبــدى املدعــى عليــه القناعــة أمــا‬\n      ‫املدعــي وكالــة فلــم يقنــع ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبكــة املكرمة برقم ‪ 3392948‬وتاريخ ‪1433/2/3‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 33243164‬وتاريــخ ‪ 1433/2/3‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1433/02/20‬ه ـ افتتحــت اجللســة الســاعة ‪9 : 30‬‬\n      ‫وفيهــا حضــر ‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ..........‬الوكيــل الشــرعي عــن املدعــي ‪ ................‬مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة عــدل الثانية بغرب مبكــة برقم ‪320302007200‬‬\n      ‫يف ‪1431/7/1‬ه ـ ولــم يحضــر املدعــى عليــه ‪ .........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ..........‬رغــم تبلغــه بنفســه لــذا فقــد قــررت‬\n      ‫ـاء علــى املــادة اخلامســة واخلمســن مــن‬‫ســماع الدعــوى والســير فيهــا بنـ ً‬\n‫‪183‬‬\n\f‫نظــام املرافعــات فادعــى املدعــي وكالــة علــى املدعــى عليــه قائــا يف‬\n‫تقريــر دعــواه‪ :‬إن املدعــى عليــه الغائــب عــن مجلــس احلكــم قــد كفــل‬\n‫كفالــة غــرم وأداء وتســليم لــدى موكلــي كمــا هــو منصــوص يف‬\n‫العقــد املرفــق والكمبيالــة رقــم ‪ 2325‬وتاريــخ ‪1432/1/20‬ه ـ وقــد قــام‬\n‫املكفــول بشــراء خمســة عشــر مكيفــا مــن نــوع ‪ ....‬مــن موكلــي مببلــغ‬\n‫وقــدره ســبعة وعشــرون ألــف ريــال مبوجــب العقــد املبــرم املرفــق باملعاملــة‬\n‫ومبوجــب الكمبيالــة ولــم يســدد مكفولــه إال مبلــغ وقــدره ألفــان ريــال‬\n‫فقــط وبقــي مبلــغ وقــدره خمســة وعشــرون ألــف ريــال وقــد حــل املبلــغ‬\n‫كامــا يف تاريــخ ‪1432/4/25‬ه ـ لــذا أطلــب احلكــم عليــه بدفــع املبلــغ‬\n‫ا هكــذا ادعــى‪ ،‬وقــد أفــاد املدعــي وكالــة يف أثنــاء اجللســة‬               ‫كام ـ ً‬\n‫بطريقــة البيــع وقــال هــي علــى النحــو التالــي ‪ :‬لقــد اشــترى املكفــول من‬\n‫موكلــي خمســة عشــر مكيفــا وبعــد املعاينــة باعهــا علــى البائــع نفســه‬\n‫هكــذا أفــاد ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫‪ ...........‬ومــن ثــم تلــي علــى املدعــى عليــه مــا ضبــط يف اجللســة الســابقة‬\n‫ا‬\n‫فأقــره وقــال ‪ :‬جميــع مــا ذكــره املدعــى وكالــة صحيــح جملــة وتفصيـ ً‬\n‫‪،‬وبســؤالهما عمــا تــودان إضافتهــا ؟ أجابــا ب ـ ‪ :‬ال يوجــد ســوى مــا ذكــر‬\n‫وباالطــاع علــى املعاملــة والنظــر يف طياتهــا والعقــد املرفــق والكمبيالــة‬\n‫املذكــورة ومــا ذكــره املدعــي وأقــره عليــه وأن ذلــك كلــه صحيــح ؛‬\n‫والعتــراف املدعــي وكالــة واملدعــى عليــه بعقــد العينــة احملــرم علــى قــول‬\n‫جماهيــر أهــل العلــم وهــو عقــد ال يصــح ‪ ،‬فــا يترتــب عليــه أي آثــر‪،‬‬\n‫ونظــر ًا الــى حــال املدعــي واملدعــى عليــه فهمـ ًا يظنــان أن مــا قامــا بــه ال‬\n‫شــيء فيــه وأنــه مــن البيــع املبــاح ‪ ،‬ولــذا فهمــا قــد رضيــا بــه ‪ ،‬إذ قــد ســلم‬\n‫املدعــي اخلمســة عشــر ألــف ريــال ورد مكفــول املدعــى عليــه ألفــن ريــال‬\n\n\n                                                                                            ‫‪184‬‬\n\f      ‫‪ ،‬لذلــك كلــه فقــد ألزمــت املدعــى عليــه ‪ .........‬بدفــع مبلــغ وقــدره ثالثــة‬\n      ‫عشــر ألــف ريــال فقــط وهــو رأس املــال ورددت دعــوى املدعــي وكالــة‬\n      ‫فيمــا زاد عــن ذلــك للســبب املذكــور آنف ـ ًا وبذلــك حكمــت مــع بيــان‬\n      ‫حقيقــة مــا جــرى بينهمــا وأنــه محــرم يف كتــاب اهلل وســنة نبيــه وأنــه مــن‬\n      ‫كبائــر الذنــوب وأن ذلــك ممحــق لبركــة املــال وإن زاد ظاهــر ًا وبعــرض‬\n      ‫احلكــم علــى الطرفــن أبــدى املدعــى عليــه القناعــة أمــا املدعــي وكالــة‬\n      ‫فلــم يقنــع وطلــب االســتئناف واســتعد بتقــدمي الئحــة اعتراضيــة وجــرى‬\n      ‫تســليمه نســخة مــن احلكــم ومت إفهامــه أن مــدة االعتــراض ثالثــون‬\n      ‫يوم ـ ًا تبــدأ مــن اســتالمه نســخة مــن احلكــم مبضــي املــدة وعــدم تقــدمي‬\n      ‫الالئحــة يســقط حقــه يف االســتئناف ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/03/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده أمــا بعــد‪ :‬ففــي يــوم األحــد املوافــق‪ 1433/10/29‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 8،45‬صباح ـ ًا وفيهــا حضــر املدعــي وكالــة‬\n      ‫واملدعــى عليــه وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف مرفــق‬\n      ‫بهــا القــرار رقــم ‪ 33351209‬وتاريــخ ‪1433/7/21‬ه ـ ونصــه « احلمــد‬\n      ‫هلل وحــده‪ ،‬والصــاة والســام علــى رســول اهلل‪ ،‬وبعــد‪ -:‬نحــن قضــاة‬\n      ‫الدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة‬\n      ‫بكتــاب فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة رقــم‬\n      ‫‪ 33243164‬وتاريــخ ‪1433/7/13‬ه ـ املشــتملة علــى احلكــم الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪ ..............‬القاضــي يف احملكمــة العامــة مبكــة‬\n      ‫املكرمــة املســجل بعــدد ‪ 33238846‬وتاريــخ ‪1433/5/10‬ه ـ املتضمــن‬\n      ‫دعــوى ‪ ............‬ضــد ‪ ...........‬احملكــوم فيــه مبــا دون الصــك‪ ،‬وبدراســة‬\n\n\n‫‪185‬‬\n\f‫احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة‬\n‫حاكمهــا ملالحظــة أن فضيلتــه أثبــت أن رأس املــال هــو خمســة عشــر‬\n‫ألــف ريــال ولــم يوضــح كيفيــة ثبــوت ذلــك‪ .‬واهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬قاضــي اســتئناف ‪..............‬‬\n‫ختــم وتوقيــع قاضــي اســتئناف ‪ ........‬ختــم وتوقيــع لــه إضافــة رئيــس‬\n‫الدائــرة ‪ ........‬ختــم وتوقيــع « ا‪.‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة عــن‬\n‫هــذه امللحوظــة أن املدعــي وكالــة واملدعــى عليــه قــد قــرروا يف اجللســة‬\n‫األولــى أن رأس املــال مبلــغ وقــدره خمســة عشــر ألــف ريــال‪ ،‬فقــد اشــترى‬\n‫مكفــول املدعــى عليــه مــن املدعــي أصالــة خمســة عشــر مكيفـ ًا بثمـ ٍـن‬\n‫آجــل قــدره ســبعة وعشــرون ألــف ريــال ثــم بــاع املشــتري علــى البائــع‬\n‫املكيفــات بثمــن حــال قــدره خمســة عشــر ألــف ريــال‪ ،‬لكــن ضبــط‬\n‫ذلــك فــات‪ ،‬وحلضــور املدعــي وكالــة واملدعــى عليــه مت ســؤالهما‬\n‫مــرة أخــرى عــن طريقــة البيــع والثمــن احلــال واملؤجــل فأجابــا بنفــس‬\n‫مــا أجابــا بــه يف اجللســة األولــى‪ ،‬هــذا مــا مت ضبطــه لرفعــه حملكمــة‬\n‫االســتئناف لتدقيقــه حســب املتبــع وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر الســاعة ‪ 9،45‬صباح ـ ًا‬\n                                                      ‫يف ‪ 1433/10/29‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫مبكــة املكرمــة والقائــم بعمــل املكتــب القضائــي رقــم (‪ )24‬هــذا‬\n‫وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف برقــم ‪34374685‬‬\n‫وتاريــخ ‪1434/3/7‬ه ـ مرفقــا بهــا قــرار التصديــق رقــم ‪3444605‬‬\n‫وتاريــخ ‪1434/2/23‬ه ـ ونصــه « احلمــد هلل وحــده والصــاة والســام‬\n‫علــى رســول اهلل وبعــد ‪ -:‬نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة‬\n\n\n                                                                                    ‫‪186‬‬\n\f      ‫اخلامســة يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا‬\n      ‫االطــاع علــى هــذا احلكــم الصــادر مــن فضيلــة الشــيخ ‪ .....‬القاضــي‬\n      ‫باحملكمــة العامــة مبكــة املكرمــة املســجل بعــدد ‪ 33238846‬وتاريــخ‬\n      ‫‪1433/5/10‬ه ـ املتضمــن دعــوى ‪ ...........‬ضــد ‪ ........‬احملكــوم فيــه‬\n      ‫مبــا دون باطــن الصــك وبدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n      ‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم قاضــي‬\n      ‫اســتئناف ‪ ...........‬ختــم وتوقيــع قاضــي اســتئناف ‪ .........‬ختــم وتوقيــع‬\n      ‫رئيــس الدائــرة ‪ ...........‬ختــم وتوقيــع «وعليــه فقــد جــرى التهميــش‬\n      ‫مبوجبــه‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                ‫يف ‪ 1434/05/27‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبكــة املكرمــة والقائــم بعمــل املكتــب القضائــي رقــم (‪ )24‬ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1434/6/20‬ه ـ حضــر املدعــي وكالــة ‪ ........‬ســعودي‬\n      ‫ا عــن املدعــي‬    ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬بصفتــه وكيـ ً‬\n      ‫وذلــك مبوجــب الوكالــة املرصــودة ســابق ًا والتــي تخولــه اإلقــرار‪،‬‬\n      ‫وقــد قــرر اســتالم موكلــه لكامــل املبلــغ احملكــوم لــه بالصــك رقــم‬\n      ‫‪ 33238846‬يف ‪1433/5/10‬ه ـ وقــدره ثالثــة عشــر ألــف ريــال ‪ ،‬وبذلك‬\n      ‫تكــون الدعــوى منتهيــة وليــس للمدعــي مطالبــة املدعــى عليــه ‪.............‬‬\n      ‫مبوضــوع هــذه الدعــوى ‪.‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/6/20‬ه ـ ‪.‬‬\n\n\n\n\n‫‪187‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":182,"source_page_end":187,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f60edec54880de9cb5a15598aee647fa73cc9d8b2389db87f466520c96869be2","normalized_text_hash":"c8ab54e8bb0e945a25aa1ed5ade0409596271494c1bf250af3030bce5382a709","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p182-33238846"},{"id":"083664c0-710d-5f66-b8ba-6b854d068aec","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع قطع أراضي -املطالبة بإثبات امللكية لأرض وإفراغها بصك امللكية -عدم صفة املدعى عليه يف الدعوى -رد الدعوى وإخاء سبيل املدعى عليه .","document_number":"3428208","case_number":"3410607","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالباحة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/3","year":"1434","subject":"بيع -بيع قطع أراضي -املطالبة بإثبات امللكية لأرض وإفراغها بصك امللكية -عدم صفة املدعى عليه يف الدعوى -رد الدعوى وإخاء سبيل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/2/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3428208 :‬‬\n                   ‫َر ْق ُم الدعوى‪3410607 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪34168643‬تاريخه‪1434/3/22 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع قطــع أراضــي ‪ -‬املطالبــة بإثبــات امللكيــة لــأرض وإفراغهــا‬\n‫بصــك امللكيــة ‪ -‬عــدم صفــة املدعــى عليــه يف الدعــوى ‪ -‬رد الدعــوى‬\n                                            ‫وإخــاء ســبيل املدعــى عليــه ‪.‬‬\n\n\n\n\n‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة والــواردة‬\n                                                           ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n‫قــام املدعــي بشــراء قطــع أراضــي مــن وكيــل مالــك األرض بوثيقــة‬\n‫مبايعــة بينهمــا دون تســليم صــك بتملكهــا ‪ -‬مت الغــاء صــك الوكالــة ‪-‬‬\n‫وملــا كانــت الدعــوى تـق ــام علــى األصيــل ال على ال ــوكيل‪ ،‬لذلك كـل ــه‬\n‫فقد ص ــدر احلك ــم برد دعوى املدعي وإخ ــاء ســبيل املدعى عليه منها‬\n‫لعــدم صفتــه يف الدعــوى وأفهــم املدعــي بــأن لــه التقــدم بدعــواه ضــد‬\n‫البائــع‪ ،‬اعتــرض املدعــي علــى احلكــم ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                               ‫االســتئناف ‪.‬‬\n\n\n\n\n                                                                                     ‫‪188‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n      ‫(‪ )....‬القاضــي يف احملكمــة العامــة بالباحــة وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالباحــة برقــم ‪3410607‬‬\n      ‫وتاريــخ ‪1434/01/06‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3447863‬وتاريــخ‬\n      ‫‪1434/01/06‬ه ـ ففــي يــوم األحــد املوافق‪1434/02/03‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة وفيهــا حضــر ‪ .........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ............‬فادعــى علــى احلاضــر معــه ‪ ...........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬قائــا يف دعــواه عليــه‪:‬‬\n      ‫إنــه بتاريــخ ‪1431/9/22‬ه ـ اشــتريت مــن املدعــى عليــه احلاضــر قطــع‬\n      ‫أراضــي تقــع يف مخطــط ‪ ......‬الواقــع يف مركــز ‪ ......‬التابــع ملنطقــة‬\n      ‫الباحــة واململوكــة بالصــك الصــادر مــن محكمــة بيــده برقــم ‪51‬‬\n      ‫وتاريــخ ‪1414/4/4‬ه ـ ‪ ،‬وهــي القطــع رقــم ‪ 674‬ورقــم ‪ 675‬ورقــم ‪676‬‬\n      ‫ورقــم ‪ 677‬والبالــغ مســاحة كل منهــا ألــف ومائتــا متــر مربــع ‪ ،‬وبقيمــة‬\n      ‫قدرهــا أربعــة عشــر ألــف ريــال لــكل قطعــة ‪ ،‬ليكــون املبلــغ اإلجمالــي‬\n      ‫مبلــغ قــدره ســتة وخمســون ألــف ريــال ســلمتها للمدعــى عليــه احلاضــر‬\n      ‫ومت كتابــة وثيقــة مبايعــة بيننــا بهــذا الشــأن يف تاريخــه ولكــن املدعــى‬\n      ‫عليــه لــم يفــرغ لــي األرض ولــم يســلم لــي صــك متلكهــا حتــى اآلن لــذا‬\n      ‫أطلــب إثبــات متلكــي لهــذه القطــع وإفراغهــا لــي ومتكينــي منهــا هــذه‬\n      ‫دعــواي وبعــرض مــا جــاء يف دعــوى املدعــي علــى املدعــى عليــه أجــاب‬\n      ‫قائــا مــا ذكــره املدعــي يف دعــواه كلــه صحيــح ولكنــي بعتــه األرض‬\n      ‫بصفتــي وكيــا عــن مالــك األرض ‪ ................‬حيــث كنــت وكيــا‬\n\n‫‪189‬‬\n\f‫عنــه حينهــا ‪ ،‬وقــد كان علــى األرض الصــك املشــار إليــه يف الدعــوى‬\n‫ولكــن مت نقضــه مــن قبــل احملكمــة العليــا لوجــود إشــكاالت ال أعلــم‬\n‫تفاصيلهــا حتديــدا وكان املدعــي علــى علــم بذلــك كلــه ‪ ،‬ولــذا فإنــه‬\n‫ال عالقــة لــي مبــا يطلبــه املدعــي والدعــوى تقــام علــى البائــع أصالــة لــذا‬\n‫أطلــب رد دعــوى املدعــي هــذه إجابتــي وبعــرض مــا جــاء يف جوابــه علــى‬\n‫املدعــي وســؤاله عنــه أجــاب بقولــه مــا ذكــره املدعــى عليــه صحيــح ‪،‬‬\n‫وكنــت علــى علــم بــأن الصــك غيــر مكتمــل وأن هــذا احلاضــر وكيــل‬\n‫عــن ‪ .............‬ولكنــي أطلــب إلزامــه كونــه مــن اســتلم املبالــغ وكتــب‬\n‫الوثائــق بالبيــع هكــذا أجــاب وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابة‬\n‫ومــا قــرره الطرفــان وحيــث صــادق املدعــي علــى مــا دفــع بــه املدعــى عليــه‬\n‫مــن كونــه وكيــا ال أصيــا يف البيــع املشــار إليــه بالدعــوى ونظــرا‬\n‫إلــى أن الدعــوى تقــام علــى األصيــل ال علــى الوكيــل كمــا هــو متقــرر‬\n‫شــرعا‪ ،‬لذلــك كلــه فقــد حكمــت بــرد دعــوى املدعــي وإخــاء ســبيل‬\n‫املدعــى عليــه منهــا لعــدم صفتــه يف الدعــوى وأفهمــت املدعــي بــأن لــه‬\n‫التقــدم بدعــواه ضــد البائــع وبعرضــه عليهمــا قــرر املدعــى عليــه قناعتــه‬\n‫باحلكــم وقــرر املدعــي اعتراضــه عليه مســتعدا بتقدمي الئحــة اعتراضية‬\n‫فأفهمتــه بــأن ســيتم تســليمه نســخة مــن صــك احلكــم هــذا اليــوم ولــه‬\n‫االعتــراض عليــه خــال ثالثــون مــن تاريــخ هــذا اليــوم وإذا لــم يتقــدم‬\n‫باعتراضــه خــال هــذه املــدة ســقط حقــه يف االعتــراض واكتســب‬\n‫احلكــم القطعيــة ففهــم ذلــك ‪ ،‬وختمــت اجللســة الســاعة العاشــرة‬\n‫والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/03‬ه ـ‬\n‫احلمد هلل وحده وبعد ويف يوم الســبت املوافق ‪1434/04/06‬هـ افتتحت‬\n\n\n                                                                                       ‫‪190‬‬\n\f      ‫اجللســة الســاعة احلاديــة عشــرة وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف مبكــة املكرمــة برقــم ‪ 34648043‬يف ‪1434/03/25‬ه ـ‬\n      ‫وبرفقهــا قــرار التصديــق الصــادر مــن الدائــرة احلقوقيــة السادســة‬\n      ‫مبحكمــة االســتئناف برقــم ‪ 34168643‬يف ‪1434/03/22‬ه ـ‬\n      ‫واملتضمــن بعــد املقدمــة مــا نصــه « وبدراســة احلكــم وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقــرر املوافقــة علــى احلكــم ‪ ،‬وبــاهلل التوفيــق‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم قاضــي اســتئناف‬\n      ‫‪ .......‬ختــم وتوقيــع قاضــي اســتئناف ‪ ..........‬ختــم وتوقيــع رئيــس الدائــرة‬\n      ‫‪ ..........‬ختــم وتوقيــع « انتهــى نصــه وقــد ظهــر مبضمونــه علــى الصــك ‪،‬‬\n      ‫وللعلــم جــرى حتريــره وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                        ‫‪ .‬حــرر يف ‪1434/04/06‬ه ـ‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد‪ :‬فق ــد ج ــرى‬\n      ‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n      ‫الصــادر مــن فضيلــة الشــيخ ‪ ......... /‬القاضــي باحملكمــة العامــة‬\n      ‫بالباحــة واملســجل بع ــدد ‪ 3428208‬وتاريــخ ‪1434/2/3‬ه ـ املتضمــن‬\n      ‫دعــوى ‪ ............‬ضــد ‪ ........‬احملكــوم في ــه مبــا دون باطنــه ‪ ،‬وبدراس ــة‬\n      ‫احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى‬\n      ‫احلكم ‪ ،‬واهلل املوفق وصل ــى اهلل عل ــى نبينا محمد وعل ــى آل ــه وصحب ــه‬\n                                                                                ‫وســلم ‪.‬‬\n\n\n\n\n‫‪191‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":188,"source_page_end":191,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fee2067ebe4423a42c30ee1e6e89fb71e5bea746ebc2c0918119407a709fc6a0","normalized_text_hash":"e0b4242b6efdae24e6ad51133260a0b8ac6f5a2c0fae9d25c5f05b8798fc043b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p188-3428208"},{"id":"7a3cc3b4-4f00-577a-afe0-d2516fc2522d","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع أرض -طلب إعادة ثمن املبيع لعدم القدرة على التسليم - اإلقرار بقبض الثمن وعدم القدرة على التسليم -األرض أماك حكومية -احلكم ببطان البيع واستعادة ثمن املبيع .","document_number":"34208897","case_number":"3413329","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة صامطة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/7","year":"1434","subject":"بيع أرض -طلب إعادة ثمن املبيع لعدم القدرة على التسليم - اإلقرار بقبض الثمن وعدم القدرة على التسليم -األرض أماك حكومية -احلكم ببطان البيع واستعادة ثمن املبيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/7 :‬هـ‬\n               ‫ُ‬                 ‫َر ْق ُم َّ‬\n                   ‫الص ِّك‪34208897 :‬‬\n                   ‫َر ْق ُم الدعوى‪3413329 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34274047‬تاريخه‪1434/7/19 :‬هـ‬\n\n\n‫بيــع أرض ‪ -‬طلــب إعــادة ثمــن املبيــع لعــدم القــدرة علــى التســليم ‪-‬‬\n‫اإلقــرار بقبــض الثمــن وعــدم القــدرة علــى التســليم ‪ -‬األرض أمــاك‬\n          ‫حكوميــة ‪ -‬احلكــم ببطــان البيــع واســتعادة ثمــن املبيــع ‪.‬‬\n\n\n\n\n‫مــن شــروط البيــع الصحيــح أن يكــون مقــدورا علــى تســليمه‪ .‬كشــاف‬\n                                                   ‫القنــاع (‪. )332/7‬‬\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى مــن املدعــي عليــه أرض ـ ًا ســكنية وســلمه‬\n‫ثمنهــا وعندمــا أراد البنــاء فيهــا منعتــه اجلهــة املختصــة مــن ذلــك لكــون‬\n‫األرض مــن أمــاك الدولــة وهدمــت الســور الــذي بنــاه فيهــا ‪ ،‬و لــذا طلــب‬\n‫إعــادة املبلــغ الــذي ســلمه للمدعــى عليــه ‪ -‬أقــر املدعــى عليــه مبــا جــاء يف‬\n‫الدعــوى ودفــع بأنــه ميلــك األرض لكــن ليــس لديــه مــا يثبــت ملكيتــه‬\n‫لهــا وال يســتطيع معارضــة الدولــة ‪ -‬املدعــى عليــه بــاع أرض ـ ًا ال صــك‬\n‫فيهــا وقــد اســتلمتها الدولــة واعتــرف أنــه ال يســتطيع أن مينــع الدولــة‬\n‫ومــن شــروط البيــع الصحيــح أن يكــون مقــدورا علــى تســليمه ‪ -‬قضــت‬\n‫احملكمــة ببطــان البيــع محــل الدعــوى وألزمــت املدعــى عليــه بإعــادة‬\n‫املبلــغ املدعــى بــه للمدعــي ‪ -‬عــارض املدعــى عليــه علــى احلكــم ‪ -‬قــررت‬\n                               ‫محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n                                                                                        ‫‪192‬‬\n\f      ‫احلمد هلل وحده وبعد فلدي أنا (‪ )....‬القاضي باحملكمة العامة مبحافظة‬\n      ‫صامطــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبحافظــة صامطــة برقــم ‪ 3413329‬وتاريــخ ‪1434/01/10‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 3462413‬وتاريــخ ‪1434/01/10‬ه ـ ففــي‬\n      ‫يــوم األحــد املوافق‪1434/03/08‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 30‬‬\n      ‫وفيهــا حضــر (‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)......‬‬\n      ‫وحضــر حلضــوره (‪ )......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ )......‬ثــم أدعــى املدعــي قائــا لقــد اشــتريت مــن هــذا احلاضــر ‪ ،‬أرض‬\n      ‫ســكنية مســاحتها ‪40‬متــر يف ‪ 50‬متــر تقــع شــمال قريــة (‪ )....‬مببلــغ‬\n      ‫ســتني ألــف ريــال وعندمــا أردت البنــاء اعترضتنــي الدولــة وقالــت هــذه‬\n      ‫األرض مــن أمــاك الدولــة وخرجــت علــي جلنــة التعديــات وهدمــت الســور‬\n      ‫الــذي بنيتــه فيهــا ثــم بعــد اعتراضــي علــى ذلــك أفادنــي أميــر املنطقــة‬\n      ‫بــان هــذه األرض ملــك مــن أمــاك الدولــة ولــك الرجــوع علــى البائــع ألنــه‬\n      ‫بــاع مــا ال ميلــك لــذا أطلــب إعــادة املبلــغ الــذي ســلمته لــه وقــدرة ســتون‬\n      ‫ألــف ريــال وأمــا مــا يتعلــق باخلســارة التــي خســرتها يف األرض مــن تســوير‬\n      ‫وردم لهــا فيعوضنــي اهلل فيهــا هــذه دعــواي ثــم جــرى عــرض ذلــك علــى‬\n      ‫املدعــى عليــة فأجــاب قائــا نعــم صحيــح مــا ذكــرة املدعــي مــن البيــع‬\n      ‫لــأرض واســتالمي للقيمــة ولكــن أنــا ال أملــك أن أمنــع الدولــة عــن هــذه‬\n      ‫األرض وقــد اشــتريتها عــام ‪1383‬ه ـ واجلــزء الــذي بعتــه للمدعــي وجــزء‬\n      ‫مــن األرض التــي اشــتريت وأنــا ال اســتطيع أن أعــارض الدولــة هكــذا‬\n      ‫أجــاب وحيــث األمــر كذلــك طلبــت مــن املدعــي حتريــر دعــواه وحتديــد‬\n\n‫‪193‬‬\n\f‫األرض بالتفصيــل ففــي يــوم االثنــن املوافــق ‪1434/05/06‬ه ـ حضــر‬\n‫املدعــي وحضــر حلضــوره املدعــى عليــه ثــم أبــرز املدعــي كروكــي‬\n‫لــأرض محــل النــزاع يــن حــدود األرض وأطوالهــا وهــو كمــا يلــي أو ًال‬\n‫‪ :‬مــن الشــمال يبــدأ مــن الغــرب بطــول ‪40‬م وبزاويــه ‪ 88‬درجــة ويحــده‬\n‫شــارع مقتــرح عــرض ‪10‬م مناصفــه بــن البائــع واملجــاور الشــيخ (‪)........‬‬\n‫ومــن اجلنــوب يبــدأ مــن الشــرق بطــول ‪40.00‬م وبزاويــه ‪ 88‬درجــة ويحــده‬\n‫البائــع (‪ )........‬و(‪ )........‬ومــن يبــدأ مــن الشــمال بطــول‪50‬م وبزاويــة ‪92‬‬\n‫درجــة ويحــده شــارع مقتــرح عــرض ‪10‬م مــن قبــل البائــع ومــن الغــرب‬\n‫يبــدأ مــن اجلنــوب بطــول ‪50‬م وبزاويــة ‪ 92‬درجــة ويحــده إســفلت (‪)........‬‬\n‫عــرض أربعــن متــر واملســاحة اإلجماليــة ألــف وتســعمائة وثمــان وتســعني‬\n‫متــر مربــع وخمســن ســنتمتر (‪1998.50‬م‪ )2‬وبعــرض ذلــك علــى املدعــى‬\n‫عليــه أجــاب قائــا نعــم هــذه حــدود األرض وصحيــح هــذا املســح ثــم أبــرز‬\n‫املدعــي صــورة خطــاب مــن وكيــل إمــارة منطقــة جــازان موجــه إلــى‬\n‫محافظــة (‪ )........‬ويفيــد أن املدعــي أشــترى األرض محــل النــزاع وأن‬\n‫جلنــة التعديــات خرجــت لــأرض وأتضــح أنهــا مــن األراضــي احلكوميــة‬\n‫ويطلــب مــن احملافظــة منــع اجلميــع مــن األرض إال مــن لديــه مستمســك‬\n‫شــرعي مكتمــل اإلجــراءات النظاميــة وإفهــام املدعــي وهــو املشــتري‬\n‫بــأن لــه احلــق يف الرجــوع بالثمــن علــى مــن باعــه‪ ...‬الــخ وبعــرض ذلــك علــى‬\n‫املدعــى عليــه أفــاد قائــا أن اخلطــاب الصــادر مــن اإلمــارة ال يعلمــون عــن‬\n‫أرضــي وأنهــا لــي وأنــا بعــت مــا أملــك هكــذا أجــاب ثــم ســألت املدعــى‬\n‫عليــه هــل جلنــة التعديــات خرجــت لــأرض و أزالــت مــا فيهــا فأجاب قائال‬\n‫نعــم ثــم ســألته هــل علــى هــذه األرض صــك شــرعي يثبــت متلــكك لهــا‬\n‫فأجــاب قائــا ال لــم أخــرج بهــا صــك شــرعي وليــس لهــا مخطــط معتمــد‬\n\n\n                                                                                        ‫‪194‬‬\n\f      ‫مــن الدولــة هكــذا أجــاب ففــي يــوم الثالثــاء املوافــق ‪1434/05/07‬ه ـ‬\n      ‫حضــر املدعــي وحضــر حلضــوره املدعــى عليــه وبعــد تأمــل مــا ســبق‬\n      ‫ضبطــه لــذا وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولكــون املدعــى‬\n      ‫عليــه بــاع أرضــا ال صــك فيهــا وقــد اســتلمتها الدولــة واعتــرف أنــه ال‬\n      ‫يســتطيع أن مينــع الدولــة ومبــا أن هــذا البيــع مخالــف للنظــام ومبــا أن مــن‬\n      ‫شــروط البيــع الصحيــح أن يكــون مقــدورا علــى تســليمه كمــا ذكــر‬\n      ‫الفقهــاء ذلــك أنظــر كشــاف القنــاع مجلــد ‪ 7‬يف صفحــة ‪ 332‬لــذا كلــه‬\n      ‫ثبــت لــدي بطــان هــذا البيــع وألزمــت املدعــى عليــه بإعــادة مبلــغ ســتني‬\n      ‫ألــف ريــال للمدعــي وهــي قيمــة البيــع هــذا مــا ظهــر لــي وبــه حكمــت‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب متكينــه‬\n      ‫تقــدمي الئحــة اعتراضيــة و أفهمتــه بــأن عليــه مراجعــة احملكمــة اليــوم‬\n      ‫بعــد الظهــر الســتالم نســخة احلكــم وأن لــه مــدة ثالثــن يوم ـ ًا ليقــدم‬\n      ‫اعتراضــه خاللهــا وإن انتهــت هــذه املــدة ولــم يقــدم اعتراضــه خاللهــا‬\n      ‫فــإن احلكــم يكتســب الصفــة القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n         ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/7‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هذا اليوم االثنــن ‪1434/08/15‬هـ افتتحت‬\n      ‫اجللســة الســاعة العاشــرة والنصــف وقــد وردتنــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف مبنطقــة عســير برقــم ‪ 341611831‬وتاريــخ ‪1434/8/8‬ه ـ‬\n      ‫وبرفقهــا قــرار تصديــق برقــم ‪ 34274047‬وتاريــخ ‪1434/07/19‬ه ـ‬\n      ‫يتضمــن املوافقــة علــى احلكــم وتنبيــه بإفهــام املدعــى عليــه بــأن إقامــة‬\n      ‫الدعــوى علــى مــن بيــده األرض وأمــرت بإحلــاق ذلــك بالضبــط والصــك‬\n      ‫وســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n                                                   ‫وســلم حــرر يف ‪1434/08/15‬هــ‪.‬‬\n\n\n‫‪195‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة العامــة مبحافظــة‬\n‫صامطــة ففــي هــذا اليــوم الثالثــاء ‪1435/01/02‬ه ـ افتتحــت اجللســة‬\n‫الســاعة احلاديــة عشــر وفيهــا حضــر املدعــي وقــرر باســتالمه لكامــل‬\n‫املبلــغ احملكــوم لــه بــه يف باطــن هــذا الصــك وأمــرت بإحلــاق ذلــك‬\n‫بالضبــط والصــك وســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                   ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1435/01/02‬ه ـ ‪.‬‬\n\n\n\n\n                                                                               ‫‪196‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":192,"source_page_end":196,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"37f045207ea7924907ff94fa4e4f5ffb0084fd0b113a0277cd8f4bbbbcae30e8","normalized_text_hash":"68a3b8cee8cf403d7b382a2a61487c8fc5049a48a1f08860bdef15ec977631c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p192-34208897"},{"id":"2c3b2896-125a-58c0-808e-65316a7d79db","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع متور واملطالبة بقيمتها -افتقاد املدعي البينة -شهادة الشهود العدول لصالح املدعى عليهما -صرف النظر عن دعوى","document_number":"34283451","case_number":"3413552","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/1","year":"1434","subject":"بيع -بيع متور واملطالبة بقيمتها -افتقاد املدعي البينة -شهادة الشهود العدول لصالح املدعى عليهما -صرف النظر عن دعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/8/1 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34283451 :‬‬\n                          ‫َر ْق ُم الدعوى‪3413552 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34344474‬تاريخه‪1434/10/29 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬بيــع متــور واملطالبــة بقيمتهــا ‪ -‬افتقــاد املدعــي البينــة ‪ -‬شــهادة‬\n      ‫الشــهود العــدول لصالــح املدعــى عليهمــا ‪ -‬صــرف النظــر عــن دعــوى‬\n                                                                             ‫املدعــي ‪.‬‬\n\n\n\n\n                        ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه بــاع للمدعــى عليهمــا متــر ًا منوع ـ ًا مببلــغ ســددا منــه‬\n      ‫مبلغ ـ ًا وبقــي مبلــغ وطلــب إلزامهمــا بالســداد حــاالً‪ -‬أنكــر املدعــى‬\n      ‫عليهمــا مــا جــاء يف الدعــوى ‪ -‬ال بينــة للمدعــي ‪ -‬أحض ــر املدعــى عليهمــا‬\n      ‫شــهود ًا ج ــرى تعديلهــم ‪ -‬ص ــدر احلكــم بصــرف النظــر عــن دعــوى‬\n      ‫املدعــي ‪ -‬اعتــرض املدعــي علــى احلكــم ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                              ‫االســتئناف ‪.‬‬\n\n\n\n\n‫‪197‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمة العامة باملدينة املنورة برقم ‪ 3413552‬وتاريخ ‪1434/01/10‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 3463615‬وتاريــخ ‪ 1434/01/10‬ه ـ يف‬\n‫يــوم األحــد املوافــق‪ 1434/02/03‬ه ـ فتحــت اجللســة الســاعة ‪08 : 00‬‬\n‫لســماع دعوى ‪ ...........‬ضد ‪ ..............‬ســعودي اجلنســية مبوجب الســجل‬\n‫املدنــي رقــم ‪ ..............‬وفيهــا حضــر املدعــى عليــه املذكــور وانتهــى‬\n‫الوقــت احملــدد ولــم يحضــر املدعــي وال وكيــلٌ ولــم يقــدم عــذر ًا مقبــو ًال‬\n‫لــذا فقــد جــرى شــطب القضيــة للمــرة األولــى ‪ ،‬ويف يــوم الثالثــاء‬\n‫املوافــق‪ 1434/04/16‬ه ـ فتحــت اجللســة الســاعة العاشــرة والنصــف‬\n‫صباحـ ًا وفيهــا حضــر املدعــي ‪ ........‬باكســتاني اجلنســية مبوجب رخصة‬\n‫اإلقامــة رقــم ‪ ..............‬وانتهــى الوقــت احملــدد ولــم يحضــر املدعــى عليــه‬\n‫ولــم يردنــا مــا يفيــد تبلغــه لــذا رفعــت اجللســة وأفهــم باحلضــور يــوم الســبت‬\n‫املوافــق ‪1434/5/25‬ه ـ الســاعة العاشــرة والنصــف صباحـ ًا ‪ ،‬ويف يــوم‬\n‫الســبت املوافــق ‪1434/5/25‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫املذكــور بعاليــه وحضــر حلضــوره كلٌ مــن ‪ ...........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...........‬و‪ ...........‬ســعودي اجلنســية مبوجــب‬\n‫ا ‪ :‬إننــي بعــت للمدعــى عليهمــا‬  ‫الســجل املدنــي رقــم ‪ ............‬وادعــى قائـ ً‬\n‫متــر ًا منوعـ ًا مببلــغ وقــدره أربــع مئــة وثالثــون ألــف ريــال ســددا منهــا مبلغـ ًا‬\n‫وقــدره مئتــان وتســعون ألــف ريــال وبقــي لــي يف ذمتهمــا مبلغ ـ ًا وقــدره‬\n‫مئــة وأربعــون ألــف ريــال لــم يســدداها حتــى اآلن وأطلــب إلزامهمــا‬\n\n                                                                                               ‫‪198‬‬\n\f      ‫بالســداد حــا ًال هــذه دعــواي وبعــرض دعــواه علــى املدعــى عليهمــا األول‬\n      ‫‪ ....‬واملدعــى عليــه الثانــي ‪ .....‬أجابــا ‪ :‬إننــا شــريكان يف داللــة التمــور يف‬\n      ‫مكتــب ‪ ...........‬وشــركائه وكان لنــا شــريك اســمه ‪......‬وقــد تــويف ومــا‬\n      ‫ادعــاه مــن أننــا اشــترينا منــه متــر ًا باملبلــغ الــذي ذكــره فليــس بصحيــح‬\n      ‫والصحيــح أن لنــا يف ذمتــه مبلغ ـ ًا وقــدره ســبع مئــة وثالثــة وثمانــون‬\n      ‫ألف ـ ًا وأربــع مئــة وخمســة وســبعون ريــا ًال وأننــا مــن نطالبــه ال العكــس‬\n      ‫ونحــن ال نبيــع وال نشــتري وإمنــا عملنــا داللــة فقــط وبســؤال املدعــي ألــك‬\n      ‫بينــة ؟‪0‬أجــاب ‪:‬ليــس لــدي بينــة ‪ ،‬وبســؤالهما ألكمــا بينة؟‪0‬أجابــا ‪:‬‬\n      ‫نعــم ومســتعدان إلحضارهــا يف اجللســة القادمــة ‪،‬ورفعــت اجللســة ليــوم‬\n      ‫الســبت ‪1434/7/29‬ه ـ الســاعة العاشــرة صباح ـ ًا ‪ ،‬ويف يــوم الســبت‬\n      ‫املوافــق‪ 1434/07/29‬ه ـ فتحــت اجللســة الســاعة العاشــرة صباح ـ ًا‬\n      ‫حضــر املدعــي واملدعــى عليهمــا املــدون هويــة كلُ منهمــا ســابق ًا‬\n      ‫ال مــن ‪ .......... :‬ســوداني اجلنســية مبوجــب‬ ‫وأحضــر املدعــى عليهمــا ك ً‬\n      ‫رخصــة اإلقامــة رقــم ‪ ......‬وعمــره ‪ 64‬ســنة وهــو موظــف محاســب لــدى‬\n      ‫املدعــى عليهمــا إقامتــه يف املدينــة حــي املصانــع وبســؤاله عمــا لديــه‬\n      ‫مــن شــهادة أجــاب ‪ :‬أشــهد هلل أن املدعــي عميــل لــدى املدعــى عليهمــا‬\n      ‫يشــتري منهمــا التمــور مــن احلــراج ويقــوم بتخزينهــا يف ثالجتــه اخلاصــة‬\n      ‫ثــم يبيعهــا مبعرفتــه ويقــوم بدفــع دفعــات ملكتــب املدعــى عليهمــا ‪.........‬‬\n      ‫وشــركائه ومــا يتبقــى مــن التمــور يرجعهــا إلــى احلــراج لبيعهــا ويحــرج‬\n      ‫عليهــا املدعــى عليهمــا وتبــاع لشــخص آخــر ويأخــذ فواتيــر مــن املكتــب‬\n      ‫املذكــور بالبيــع والشــراء كلمــا طلــب ذلــك ويأخــذ إيصــال ســند قبــض‬\n      ‫باملبالــغ التــي يدفعهــا وإذا حولــت لــه مبالــغ مــن شــخص آخــر تنــزل يف‬\n      ‫ـاء علــى طلبــه ويف آخــر تعامــل لــه مــع املكتــب كان يف تاريــخ‬   ‫حســابه بنـ ً‬\n\n‫‪199‬‬\n\f‫‪1431/7/28‬ه ـ وكان املتبقــي عليــه ‪ 783475.30‬ريــا ًال ومــازال يف‬\n‫ذمتــه للمكتــب واهلل علــى مــا أقــول شــهيد‪ .‬وأحضــرا ‪ ..............‬ســوداني‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ........‬وعمــره ‪ 35‬ســنة ومحــل‬\n‫إقامتــه يف املدينــة املنــورة احلــرة الشــرقية وهــو مســتخرج الفواتيــر عــن‬\n‫طريــق احلاســب اآللــي لــدى مكتــب ‪ ..........‬وشــركائه وبســؤاله عمــا‬\n‫لديــه أجــاب ‪ :‬أشــهد هلل أن املدعــي ‪ .............‬كان يشــتري مــن مكتــب‬\n‫‪ .................‬وشــركائه متــور ًا ويأخــذ مــن عنــدي الفواتيــر بعــد تســجيلها‬\n‫ـراء أو بيعـ ًا وكذلــك إذا دفــع مبلغـ ًا يتــم عمــل‬\n                                                   ‫يف دفتــر احلســاب ســواء شـ ً‬\n‫ســند قبــض لــه وينــزل علــى هــذا املبلــغ يف الدفتــر ويف اجلهــاز وهــو مديــن‬\n‫للمكتــب يف الوقــت مببلــغ ‪ 783475.30‬ريــا ًال لــم يســدد منهــا شــيئ ًا‬\n‫واهلل علــى مــا أقــول شــهيد‪ .‬وبعــرض شــهادتهما علــى املدعــي أجــاب ‪:‬‬\n                                                  ‫الشــاهدان عامــان لديهمــا ‪.‬‬\n‫ال مــن ‪:‬‬‫لــذا طلبــت مــن املدعــى عليهمــا تعديــل الشــاهدين فأحضــرا ك ً‬\n‫‪ ................‬مصري اجلنســية مبوجب رخصة اإلقامة رقم ‪.......................‬‬\n‫وعمــره ‪ 59‬ســنة وهــو موظــف يف املكتــب املذكــور وإقامتــه يف املدينــة‬\n‫حــي املغيســلة و‪ ................‬مصــري اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n‫‪ .............‬وعمــره ‪ 44‬ســنة وهــو موظــف يف املكتــب املذكــور وإقامتــه‬\n‫يف املدينــة حــي املغيســلة وبســؤالهما عــن الشــاهدين أجابــا ‪ :‬نشــهد هلل‬\n‫أن الشــاهدين عــدالن مقبــوال الشــهادة محافظــان علــى الصــاة وعلــى‬\n‫صيــام االثنــن واخلميــس هكــذا شــهدا‪ .‬ولــذا أفهمــت املدعــي بأنــه ليــس‬\n‫لــه إال ميــن املدعــى عليهمــا فاســتعدا بذلــك وقــرر املدعــي ‪ :‬ال أطلــب‬\n‫ميينهمــا ألنهمــا ســيكذبان فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n‫وإنــكار املدعــى عليهمــا وعــدم بينــة املدعــي وإحضــار املدعــى عليهمــا‬\n\n\n                                                                                       ‫‪200‬‬\n\f      ‫البينــة املعدلــة املعارضــة لدعــوى املدعــي فقــد صرفــت النظــر عــن طلــب‬\n      ‫املدعــي وأخليــت ســبيل املدعــى عليهمــا وأفهمتــه بأنــه ليــس لــه إال ميــن‬\n      ‫املدعــى عليهمــا متــى طلبهــا هــذا مــا ظهــر لــي وبــه حكمــت وبإعالنــه‬\n      ‫علــى األطــراف قــرر املدعــي عــدم القناعــة لــذا قــررت تســليم املدعــي‬\n      ‫نســخة مــن احلكــم لتقــدمي اعتراضــه خــال املــدة النظاميــة وإال ســوف‬\n      ‫يكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫بخطــاب رئيســها رقــم ‪ 3463615‬وتاريــخ ‪1434/11/4‬ه ـ وبرفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة احلقوقيــة اخلامســة برقــم ‪34344474‬‬\n      ‫وتاريــخ ‪1434/10/29‬ه ـ ونــص احلاجــة منــه ‪ :‬وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم أ‪.‬ه ـ نــص‬\n      ‫احلاجــة منــه قاضــي اســتئناف ‪ .............‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫‪ ...........‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ .................‬ختمــه وتوقيعــه وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                            ‫حــرر يف ‪ 1434/11/24‬ه ـ ‪.‬‬\n\n\n\n\n‫‪201‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":197,"source_page_end":201,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d831f298a2b145315fe366c29110578ec81e375932e5dca8a31f98038a8dbd5","normalized_text_hash":"c67a23cb9799845afe12fa193908032e7d2ae087ec217939390c595776603cb2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p197-34283451"},{"id":"52cc49b6-4cf0-5f95-8081-c6cfc296c4b0","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -شراء منزل -دعوى على ولي قاصر بإثبات شراء عقار واحلكم بإفراغه -اعتبار إقرار املدعى عليه البالغ شهادة يف حق املدعى عليه القاصر -ال يقض على القاصر إال ببينة -صحه البيع واستالم الثمن والتهميش على صك امللكية بانتقال امللك .","document_number":"34183471","case_number":"3434349","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف يف الساعة التاسعة من هذا اليوم االثنن املوافق 1434/2/11ه عقدت اجللسة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/9","year":"1434","subject":"بيع -عقار -شراء منزل -دعوى على ولي قاصر بإثبات شراء عقار واحلكم بإفراغه -اعتبار إقرار املدعى عليه البالغ شهادة يف حق املدعى عليه القاصر -ال يقض على القاصر إال ببينة -صحه البيع واستالم الثمن والتهميش على صك امللكية بانتقال امللك .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/9 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34183471 :‬‬\n                    ‫َر ْق ُم الدعوى‪3434349 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34216809‬تاريخه‪1434/5/20 :‬هـ‬\n\n\n‫بيــع ‪ -‬عقــار ‪ -‬شــراء منــزل ‪ -‬دعــوى علــى ولــي قاصــر بإثبــات شــراء‬\n‫عقــار واحلكــم بإفراغــه ‪ -‬اعتبــار إقــرار املدعــى عليــه البالــغ شــهادة يف‬\n‫حــق املدعــى عليــه القاصــر ‪ -‬ال يقــض علــى القاصــر إال ببينــة ‪ -‬صحــه‬\n‫البيــع واســتالم الثمــن والتهميــش علــى صــك امللكيــة بانتقــال امللــك ‪.‬‬\n\n\n\n\n‫‪ -1‬ال يقــض علــى القاصــر إال ببينــه قــال يف كشــاف القنــاع ‪159/15‬‬\n‫(وإن ادعــى علــى غائــب مســافة قصــر ولــو يف غيــر عملــه أو ادعــى علــى‬\n‫ممتنــع مــن احلضــور ملجلــس احلكــم أي مســتتر إمــا يف البلــد أو يف مــا‬\n‫دون مســافة قصــر أو ادعــى علــى ميــت أو صغيــر أو مجنــون بــا بينــة‬\n‫لــم تســمع دعــواه ألنــه ال فائــدة فيهــا ولــم يحكــم لــه مبــا ادعــاه حلديــث‬\n‫(لــو يعطــى النــاس بدعواهــم) وإن كان لــه بينــة ســمعها احلاكــم‬\n                                           ‫وحكــم بهــا يف حقــوق اآلدميــن)‪.‬‬\n                                           ‫‪ -2‬املادة (‪ )179‬من نظام املرافعات‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليهــم ومــن ضمنهــم ولــي قاصــر أنــه اشــترى‬\n‫منهــم ومــن مــورث القاصــر قبــل وفاتــه بيت ـ ًا مت تســليم ثمنــه ‪ -‬طلــب‬\n‫املدعــي إثبــات هــذا الشــراء وإفــراغ صــك البيــت باســمه ‪ -‬أقــر املدعــى‬\n\n                                                                                       ‫‪202‬‬\n\f      ‫عليهــم مبــا جــاء يف دعــوى املدعــى ‪ -‬حيــث إنــه ال يقــض علــى القاصــر‬\n      ‫إال ببينــه جــرى طلــب البينــة مــن املدعــى ‪ -‬قــرر أن البينــة شــهادة املدعــى‬\n      ‫عليهــم ‪ -‬شــهد اثنــان مــن املدعــى عليهــم بصحــة مــا ورد يف الدعــوى‪-‬‬\n      ‫جــرى تعديــل الشــاهدين ‪ -‬جــرى االستفســار عــن ســريان مفعــول الصــك‬\n      ‫موضــع الدعــوى ‪ -‬وردت اإلجابــة بــأن الصــك ســاري املفعــول‪ -‬صــدر‬\n      ‫احلكــم بصحــة البيــع واســتالم الثمــن والتهميــش علــى صــك امللكيــة‬\n      ‫بانتقــال امللــك للمدعــى بعــد اكتســاب احلكــم القطعية‪ -‬رفعــت املعاملة‬\n      ‫حملكمــة االســتئناف لوجــود قاصــر ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                         ‫االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا (‪ )....‬القاضــي باحملكمــة العامــة بالطائــف يف الســاعة التاســعة‬\n      ‫مــن هــذا اليــوم االثنــن املوافــق ‪1434/2/11‬ه ـ عقــدت اجللســة للنظــر‬\n      ‫يف دعــوى ‪ ......‬ضــد ‪...‬ورفقــاه بطلــب إثبــات شــراء عقــار املقيــدة برقــم‬\n      ‫‪ 34165820‬يف ‪1434/1/19‬ه ـ واحملالــة مــن فضيلــة الرئيــس برقــم‬\n      ‫‪ 3434349‬يف ‪1434/1/19‬ه ـ ويف هــذه اجللســة حضــر ‪ ......‬ســعودي‬\n      ‫ا عــن املدعــي ‪ ...‬مبوجــب الوكالة‬   ‫بالســجل املدنــي رقــم ‪...‬بصفتــه وكيـ ً‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة برقــم ‪33485487‬‬\n      ‫يف ‪1433/12/27‬ه ـ والتــي تخولــه حــق املدافعــة واملرافعــة واإلقــرار‬\n      ‫واإلنــكار والصلــح وادعــى علــى احلاضريــن معــه ‪...‬ســعودي بالســجل‬\n      ‫املدنــي رقــم ‪...‬و‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬و‪...‬ســعودي بالســجل‬\n      ‫املدنــي رقــم ‪...‬أصالــة عــن نفســه وبصفتــه وكيــا عــن ‪...‬مبوجــب‬\n\n‫‪203‬‬\n\f‫الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة بالطائــف برقــم ‪28326‬‬\n‫ا عــن ‪...‬مبوجــب الوكالــة الصــادرة‬        ‫يف ‪1432/6/5‬ه ـ وبصفتــه وكي ـ ً‬\n‫مــن كتابــة العــدل الثانيــة بالطائــف ‪ 34141028‬يف ‪1434/2/5‬ه ـ‬\n‫ا عــن ‪...‬مبوجــب الوكالــة الصــادر مــن كتابــة العــدل‬         ‫وبصفتــه وكي ـ ً‬\n‫الثانيــة بالطائــف برقــم ‪ 34139175‬يف ‪1434/2/5‬ه ـ أصالة عن نفســها‬\n‫وبصفتهــا وليــة علــى ‪ ...‬و‪ ...‬و‪ ...‬أبنــاء ‪...‬مبوجــب صــك الواليــة الصــادر‬\n‫مــن هــذه احملكمــة برقــم ‪ 17/1/27‬يف ‪1432/5/15‬ه ـ قائــا يف دعواه‬\n‫لقــد اشــترى موكلــي مــن املدعــى عليهــم احلاضريــن ومــن ‪ ...‬مــورث‬\n‫موكلــي احلاضــر ‪ ....‬بتاريــخ ‪1432/2/1‬ه ـ بيتـ ًا مــن دور واحــد يقــع بحي‬\n‫املــاوي مبكــة املكرمــة وحــدوده شــرق ًا وشــام ًا ملــك ‪...‬وغربـ ًا الشــارع‬\n‫العــام وجنوب ـ ًا ملــك ‪...‬واململــوك مبوجــب الصــك الصــادر مــن كتابــة‬\n‫عــدل مكــة برقــم ‪ 3/161/42‬يف ‪ 1411/6/7‬بثمــن قــدره مليــون ريــال‬\n‫ا ولــم يفرغــوا ملوكلــي حتــى اآلن لــذا أطلــب ســؤالهم‬       ‫اســتلموه كام ـ ً‬\n‫وإثبــات شــراء موكلــي لهــذا البيــت وإفــراغ صكــه باســمه هــذه دعــواي‬\n‫ا مــا ذكــره‬  ‫وبعرضهــا علــى املدعــى عليهــم أجــاب كل واحــد منهــم قائـ ً‬\n‫املدعــي وكالــة يف دعــواه صحيــح وقــد اســتلمنا وأخينــا ‪ ...‬رحمــه اهلل‬\n‫قبــل وفاتــه الثمــن وقــدره مليــون ريــال وال مانــع لدينــا مــن إفراغــه باســم‬\n‫املشــتري املدعــي أصالــة ‪...‬هكــذا أجــاب كل واحــد منهــم وأضــاف‬\n‫ا بــأن أخــي ‪...‬تــويف وانحصــر ارثــه يف موكلــي ومــن‬    ‫املدعــى عليــه ‪...‬قائـ ً‬\n‫حتــت واليــة موكلتــي ‪ ...‬حســب صــك حصــر الورثــة الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 17/1/31‬يف ‪1432/5/15‬ه ـ هكــذا أضــاف ومبــا أن‬\n‫مــن املدعــى عليهــم قاصــر ســألت املدعــي وكالــة ألــك بينــة علــى دعــواك‬\n‫قــال نعــم شــهادة املدعــى عليهــم احلاضريــن وقــد شــهد كل مــن ‪...‬و‪...‬‬\n\n\n                                                                                        ‫‪204‬‬\n\f      ‫قائــا لقــد بعنــا وأخوينــا ‪ ......‬و‪ ...‬قبــل وفاتــه البيــت اململــوك لنــا جميعــا‬\n      ‫الواقــع باملــاوي مبكــة املكرمــة اململــوك بالصــك الصــادر مــن كتابــة‬\n      ‫عــدل مكــة برقــم ‪ 3/161/42‬يف ‪1411/6/7‬ه ـ علــى ‪...‬مبليــون ريــال‬\n      ‫واســتلمنا الثمــن كامــا قبــل وفــاة أخينــا ‪...‬هكــذا شــهد كل منهمــا‬\n      ‫فجــرى االطــاع علــى صــك حصــر الورثــة فوجــد يتضمــن مــا عطــف‬\n      ‫عليــه يف جــواب املدعــى عليــه ‪...‬كمــا جــرى االطــاع علــى صــك الواليــة‬\n      ‫رقــم ‪ 17/1/27‬يف ‪1432/5/15‬ه ـ فوجــد يتضمــن إقامــة ‪...‬وليــة علــى‬\n      ‫القاصريــن ‪...‬و ‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬كمــا جــرى االطــاع علــى الصــك‬\n      ‫الصــادر مــن كتابــة عــدل مكــة املكرمــة وما أحلق عليــه فوجد يتضمن‬\n      ‫بــأن احملــدود املذكــور فيــه الكائــن مبحلــة املــاوي مبكــة املكرمــة‬\n      ‫وحــدوده كمــا ذكــر املدعــي يف دعــواه أصبــح مــن أمــاك كل مــن ‪...‬‬\n      ‫و‪ ...‬و‪...‬أبنــاء ‪...‬بالتســاوي أ‪.‬ه ـ ونظــر ًا إلــى أن ‪...‬موكلــة املدعــى عليــه‬\n      ‫‪...‬لــم يتــم إثبــات بلوغهــا ورشــدها جــرى إفهامــه بذلــك فاســتعد بإثباتــه‬\n                ‫وطلــب مهلــة لــذا ولالستفســار عــن صــك العقــار رفعــت اجللســة‬\n      ‫ثــم عقــدت اجللســة وفيهــا حضــر املدعــي وكالــة ‪...‬واملدعــى عليــه أصالــة‬\n      ‫ووكالــة ‪...‬واملدعــى عليهمــا ع‪...‬و ‪...‬وقــال املدعــى عليــه وكالــة ‪...‬بأنه مت‬\n      ‫إثبــات بلــوغ و‪.........‬وقامــت بتوكيلــي وأبــرز صــك حصــر الورثــة والواليــة‬\n      ‫املشــار إليهمــا فوجــدا قــد أحلــق عليهمــا بتاريــخ ‪1434/2/17‬ه ـ ثبــوت‬\n      ‫بلــوغ و‪......‬وأبــرز املدعــى عليــه ‪...‬وكالــة عــن ‪...‬صــادرة مــن كتابــة عــدل‬\n      ‫الثانيــة بالطائــف برقــم ‪ 3414028‬يف ‪1434/2/5‬ه ـ وبســؤال املدعــي‬\n      ‫وكالــة عــن املعدلــن قــال أحضرتهمــا وأطلــب ســماع مــا لديهمــا فحضــر‬\n      ‫كل مــن ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬و ‪...‬ســعودي بالســجل املدنــي‬\n      ‫رقــم ‪...‬وشــهد كل واحــد منهمــا بــأن الشــاهدين ‪...‬و‪ ...‬ابنــي ‪...‬عــدالن‬\n\n\n‫‪205‬‬\n\f‫ثقتــان هــذا وقــد جــرى االستفســار مــن كتابــة العــدل األولــى مبكــة‬\n‫عــن الصــك رقــم ( ‪ ) 3/161/42‬يف ‪1411/6/7‬ه ـ فــورد جــواب فضيلــة‬\n‫رئيســها برقــم ‪ 34407199‬يف ‪1434/2/26‬ه ـ يتضمــن نفيدكــم أنــه‬\n‫بالبحــث يف ســجالت اإلدارة لدينــا تبــن أن الصــك رقــم ‪ 3/161/42‬يف‬\n‫‪1411/6/7‬هـ مطابق لســجله وســاري املفعول حتى تاريخه أ‪.‬هـ وبســؤال‬\n‫الطرفــن هــل لديهــم إضافــة علــى مــا ســبق قــاال ليــس لدينــا أي إضافــة‬\n‫فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي وكالــة وإجابــة وإقــرار املدعــى‬\n‫عليهــم بالبيــع واســتالم ثمــن املبيــع ونظــر ًا إلــى أن مــن ضمــن املدعــى‬\n‫عليهــم قاصــر وال يقضــى عليــه إال ببينــة قــال يف كشــاف القنــاع (( وإن‬\n‫ادعــى علــى غائــب مســافة قصــر ولــو يف غيــر عملــه أو ادعــى علــى ممتنــع‬\n‫مــن احلضــور ملجلــس احلكــم أي مســتتر إمــا يف البلــد أو يف دون مســافة‬\n‫قصــر أو ادعــى علــى ميــت أو صغيــر أو مجنــون بــا بينــة لــم تســمع دعــواه‬\n‫ألنــه ال فائــدة فيهــا ولــم يحكــم لــه مبــا ادعــاه حلديــث ( لــو يعطــى النــاس‬\n‫بدعواهــم) وإن كان لــه بينــة ســمعها احلكــم وحكــم بهــا يف حقــوق‬\n‫اآلدميــن )) أ‪.‬ه ـ (‪ )15/159‬ولشــهادة املدعــى عليهمــا ‪...‬و‪...‬املعدلــن‬\n‫وهــي مقبولــة لعــدم وجــود مانــع فيهــا وبعــد االطــاع علــى الصكــوك‬\n‫املشــار إليهــا فقــد ثبــت لــدي بيــع كل مــن ‪...‬و‪ ...‬و‪ ......‬و‪ ...‬أبنــاء ‪...‬العقــار‬\n‫املوصــوف بالدعــوى اململــوك بالصــك الصــادر مــن كتابــة العــدل األولــى‬\n‫مبكــة املكرمــة برقــم ‪ 3/161/42‬يف ‪1411/6/7‬ه ـ علــى املدعــي‬\n‫أصالــة ‪...‬ســجل مدنــي رقــم (‪ )...‬بثمــن اســتلموه قــدره مليــون ريــال وبذلك‬\n‫حكمــت وســيتم التهميــش علــى صــك امللكيــة بذلــك بعــد اكتســاب‬\n‫احلكــم الصفــة القطعيــة وبإعــان احلكــم قــرر الطرفــان القناعــة‬\n‫وأفهمتهــم بــأن هــذا احلكــم يجــب تدقيقــه ألن مــن بــن احملكــوم عليهــم‬\n\n\n                                                                                            ‫‪206‬‬\n\f      ‫ولــي قاصــر وذلــك وفــق املــادة (‪ )179‬مــن نظــام املرافعــات وأمــرت برفعــه‬\n      ‫مــع كامــل أوراق املعاملــة حملكمــة االســتئناف وبــاهلل التوفيــق حــرر يف‬\n      ‫‪1434/4/9‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                               ‫أجمعــن ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي متــام الســاعة احلاديــة عشــرة والنصــف مــن‬\n      ‫هــذا اليــوم األحــد املوافــق ‪1434/6/11‬ه ـ عقــدت اجللســة وقــد عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف بخطــاب فضيلــة رئيســها رقــم‬\n      ‫‪ 34165820‬يف ‪1434/5/29‬ه ـ احملــال لنــا بشــرح فضيلــة الرئيــس رقــم‬\n      ‫‪ 34165820‬يف ‪1434/6/10‬ه ـ ومعهــا قــرار الدائــرة الثانيــة لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال رقــم ‪34216809‬‬\n      ‫يف ‪1434/5/20‬ه ـ وقــد ظهــر الصــك مبــا نصــه « تظهيــرات الدائــرة‬\n      ‫الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت‬\n      ‫املــال مبحكمــة االســتئناف مبكــة املكرمــة احلمــد هلل وحــده وبعــد‬\n      ‫فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 34183471‬وتاريــخ ‪1434/4/9‬ه ـ‬\n      ‫الصــادر مــن فضيلــة الشــيخ ‪ ...‬وأصدرنــا القــرار رقــم ‪ 34216809‬وتاريخ‬\n      ‫‪1434/5/20‬ه ـ املتضمــن تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل‬\n      ‫املوفــق عضــو ‪ ...‬توقيعــه وختمــه عضــو د‪... /‬لــي وجهــة نظــر توقيعــه‬\n      ‫وختمــه رئيــس الدائــرة ‪ ...‬توقيعــه وختمــه « أ‪.‬ه ـ لــذا جــرى إحلاقــه وبــاهلل‬\n                                                  ‫التوفيــق حــرر يف ‪1434/6/11‬ه ـ ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n      ‫الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n      ‫علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ ... /‬القاضــي باحملكمــة العامة‬\n\n\n‫‪207‬‬\n\f‫بالطائــف املــؤرخ يف ‪1434/4/9‬هـ واملســجل بعــدد ‪ 34183471‬املتضمن‬\n‫دعــوى‪... /‬ضــد‪... /‬ورفقــاه يف إثبــات شــراء عقــار ‪ ،‬وبدراســة الصــك‬\n‫وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل املوفــق‬\n                ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":202,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"04fd598aa3bbd3e19b7f013e6a683181c3c40e890de6f404e9f7989395ee4cdc","normalized_text_hash":"2d80c34eb60c1aacf147fc5a1278619629834fc288f97b64eed8d1c978eb5b23","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p202-34183471"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

